def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    if n == 2:
        if history[0][1] == 'D' or history[1][1] == 'D':
            pass
        else:
            return 'D'
    if n == 3:
        if history[2][0] == 'D':
            return 'D'

    did_test = (n >= 3 and history[0][1] == 'C' and history[1][1] == 'C')
    if did_test and n >= 4:
        if history[3][1] == 'C':
            recent_opp_d = sum(1 for i in range(max(0, n-5), n) if history[i][1] == 'D')
            if recent_opp_d >= 4 and rng.random() < 0.3:
                return 'C'
            return 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    if n >= 8 and opp_c == 0:
        return 'D'

    recent_n = min(10, n)
    recent_opp_c = sum(1 for i in range(n - recent_n, n) if history[i][1] == 'C')
    if recent_opp_c >= recent_n - 1:
        if n >= 97:
            return 'D'
        if n >= 10 and recent_n >= 5 and rng.random() < 0.15:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        if last_my == 'D':
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        else:
            if n >= 98:
                return 'D'
            return 'C'
    else:
        opp_d_streak = 0
        for i in range(n-1, -1, -1):
            if history[i][1] == 'D':
                opp_d_streak += 1
            else:
                break

        if last_my == 'C':
            if opp_d_streak >= 4:
                return 'C'
            return 'D'
        else:
            if opp_d_streak >= 3:
                return 'C'
            return 'D'
